!function(e){function r(r){for(var a,i,d=r[0],o=r[1],m=r[2],s=0,f=[];s<d.length;s++)i=d[s],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&f.push(n[i][0]),n[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(c&&c(r);f.length;)f.shift()();return p.push.apply(p,m||[]),t()}function t(){for(var e,r=0;r<p.length;r++){for(var t,i=p[r],d=!0,o=1;o<i.length;o++)t=i[o],0!==n[t]&&(d=!1);d&&(p.splice(r--,1),e=a(a.s=i[0]))}return e}function a(r){if(i[r])return i[r].exports;var t=i[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,a),t.l=!0,t.exports}var i={},n={93:0},p=[];a.m=e,a.c=i,a.d=function(e,r,t){a.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,r){if(1&r&&(e=a(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(a.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var i in e)a.d(t,i,function(r){return e[r]}.bind(null,i));return t},a.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(r,"a",r),r},a.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},a.p="";var d=window.webpackJsonp=window.webpackJsonp||[],o=d.push.bind(d);d.push=r,d=d.slice();for(var m=0;m<d.length;m++)r(d[m]);var c=o;p.push([142,0]),t()}({142:function(e,r,t){"use strict";t.r(r);var a=t(0);Object(a.a)("de","army",t(143),t(1))},143:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轮式装甲车","link":"de_army#de_army_wav"}],"model":"Sdkfz 231型轮式（8轮）装甲侦察车","description":"<p>Sdkfz 231是德军在二战前研制的一种8轮的轮式装甲车，主要是作战场侦察用途。该车的8轮皆可独立驱动和转向，运行时灵活，有很好的机动性，该车具有较高的车速，而且8轮的配备使车子也具备了较好的越野能力，能通行泥泞等较差的路况。但8轮装甲车的底盘结构复杂，生产成本高且生产周期长，因此产量难以提高，而且该车由于车身较高，装甲防护也不强，因此也影响了它的生存力。</p><p>Sdkfz 231（8X8）轮式装甲侦察车在1937正式量产并交付给德军的侦察部队，由于同期还生产同系列（不同型号）的8轮装甲车，因此统计数量有众多不同，从1936年至1943年，约生产了数百辆。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_wav231_11.jpg","description":"<h6>Sdkfz 231型轮式（8轮）装甲侦察车</h6><p>Sdkfz 231轮式（8轮）装甲侦察车长5.85米，宽2.2米，高2.35米，车重8.3吨；发动机输出功率155马力，最高车速90～100千米/小时，最大行程300千米；</p><p>Sdkfz 231装甲厚度5.5～14.5毫米（后期正面装甲增至30毫米，车重也增至9.1吨），轮胎具有防弹能力。</p><p>Sdkfz 231武器配备为1门KWK30型（或KWK38型）20毫米机关炮，一挺MG34型7.92毫米并列机枪，炮塔为手动操作。</p><p>Sdkfz 231核载乘员4人，1名驾驶员，1名车长，1名炮手和1名无线通讯员。</p>","caption":""}],"part2title":"战场上的Sdkfz 231型轮式（8轮）装甲侦察车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_wav231_21.jpg","description":"1940年5月，西线战场荷兰阿姆斯特丹，隶属德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师师属侦察营的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_22.jpg","description":"1941年4月，非洲战场利比亚地区，隶属德军第5轻装师第3侦察营的一辆Sdkfz 231轮式（8轮）装甲侦察车。注意该车的车头正面安装了一个突出的带孔钢板，这是1940年前生产的车型所加的一个8毫米装甲防盾，钢板打孔是起到减重作用，1942年将该型车正面装甲增至30毫米后，就取消了这个防盾。","caption":""},{"image":"imgs/de/army/de_army_wav231_23.jpg","description":"1941年夏天，东线苏联战场，隶属德国武装党卫军第2“帝国”装甲师的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_24.jpg","description":"1942年12月，非洲战场突尼斯地区，隶属德军第10装甲师第10侦察营的一辆Sdkfz 231轮式（8轮）装甲侦察车。该车也是安装了装甲防盾。","caption":""},{"image":"imgs/de/army/de_army_wav231_25.jpg","description":"1943年，西线战场意大利地区，隶属德军第15装甲掷弹兵师的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_26.jpg","description":"1943年7月，东线苏联战场库尔斯克地区，隶属德国武装党卫军第2“帝国”装甲师第2党卫军侦察营的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_27.jpg","description":"1944年7月，西线法国战场诺曼底地区，隶属德国武装党卫军第12“希特勒青年团”装甲师第12侦察营的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_28.jpg","description":"1945年3月，东线战场匈牙利地区，隶属德军“统帅堂”第2装甲师的一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_29.jpg","description":"1939年9月，波兰战场，德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师的一辆Sdkfz 231轮式（8轮）装甲侦察车正在为一队在作战间隙中休息的德军士兵进行警戒。","caption":""},{"image":"imgs/de/army/de_army_wav231_30.jpg","description":"1940年3月，德军第6装甲师的一辆Sdkfz 231轮式（8轮）装甲侦察车正在进行训练。","caption":""},{"image":"imgs/de/army/de_army_wav231_31.jpg","description":"1941年～1942年间，东线苏联战场，德军侦察队俘获了一群苏军俘虏，俘虏旁边停着一辆Sdkfz 231轮式（8轮）装甲侦察车和Sdkfz 232轮式（8轮）装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav231_32.jpg","description":"1943年，在希腊地区行进的某德军装甲师一辆Sdkfz 231轮式（8轮）装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav231_33.jpg","description":"1943年7月，德军第15装甲掷弹兵师的Sdkfz 231轮式（8轮）装甲侦察车正在与德军大部队一起向前线进发。","caption":""},{"image":"imgs/de/army/de_army_wav231_34.jpg","description":"1944年西线战场，德国党卫军第12“希特勒青年团”装甲师的一辆Sdkfz 231轮式（8轮）装甲侦察车正在法国一城市执行侦察任务。","caption":""}]}')}});